dtsPropsFor.Button:
/** "brand" = the red CTA (one per panel); "secondary" = bordered, card-filled chrome. */
  tone?: "brand" | "secondary";
  /** "block" = full width (wrap it in a sized element to size it); "inline" = content width; "icon" = glyph only, needs `name`. */
  shape?: "block" | "inline" | "icon";
  /** A lucide-react icon (or any component taking className), drawn at 16px before the label. */
  icon?: React.ComponentType<{ className?: string }>;
  /** Screen-reader name; required when shape is "icon", never set otherwise. */
  name?: string;
  /** The label. Required for block/inline; for icon it shows from the sm breakpoint up. */
  children?: React.ReactNode;
  type?: "button" | "submit";
  onClick?: (e: React.MouseEvent<HTMLButtonElement>) => void;
  disabled?: boolean;
  className?: string;

dtsPropsFor.SocialButton:
/** A lucide-react icon or VenmoIcon/TikTokIcon/PatreonIcon; drawn with size={20}. */
  icon: React.ComponentType<{ size?: number }>;
  /** Accessible name and tooltip. */
  label: string;
  href: string;

dtsPropsFor.PanelHeader:
/** Glyph in the sigil box, e.g. a lucide-react icon. */
  icon: React.ComponentType<{ className?: string }>;
  title: string;
  /** The quieter line under the title. */
  sub: React.ReactNode;
  /** Optional Pill on the right. */
  badge?: string;
  /** Amber "featured" lighting; only one block on a page wears it. */
  lit?: boolean;

dtsPropsFor.Pill:
/** Optional lucide-react glyph, drawn with size={12}. */
  icon?: React.ComponentType<{ size?: number; "aria-hidden"?: boolean }>;
  children: React.ReactNode;

dtsPropsFor.LinkRow:
link: {
    /** lucide-react icon shown in the row's icon box. */
    icon: React.ComponentType<{ className?: string }>;
    title: string;
    /** Mono caption under the title, e.g. "TIKTOK · @TIBBIEX". */
    meta: string;
    href: string;
    /** true -> trailing ExternalLink glyph; otherwise a ChevronRight. */
    external?: boolean;
  };
  /** Given -> the row is a <button> calling this; omitted -> an <a href>. */
  onOpen?: () => void;

dtsPropsFor.ShopCard:
item: {
    id: string;
    /** Product name. */
    item: string;
    /** Photo URL. */
    image: string;
    alt?: string;
    blurb?: string;
    /** USD, before shipping. Either price or formats. */
    price?: number;
    sizes?: { label: string; soldOut?: true }[];
    /** Several formats, e.g. sticker / patch / tee; the card shows the lowest price as "from". */
    formats?: { id: string; label: string; price: number }[];
    stock?: { left: number; of: number };
  };
  onOpen: () => void;

dtsPropsFor.SupporterRow:
supporter: { name: string; msg: string; amount: number };
  /** 1-based position in the ranking. */
  rank: number;

dtsPropsFor.AlbumTile:
album: {
    id: string;
    album: string;
    band: string;
    year: string;
    /** Her role on the record, e.g. "Bass, vocals". */
    role: string;
    /** Cover image URL. */
    image: string;
    track?: string;
  };
  onOpen: () => void;

dtsPropsFor.PhotoGrid:
/** width/height reserve the masonry space before the image loads. */
  photos: { src: string; alt: string; width: number; height: number }[];
  onOpen: (index: number) => void;

dtsPropsFor.Lightbox:
state: {
    photos: { src: string; alt: string; width: number; height: number }[];
    index: number;
  };
  /** Called with the next state when the arrows step through photos. */
  onChange: (next: { photos: { src: string; alt: string; width: number; height: number }[]; index: number }) => void;
  onClose: () => void;

dtsPropsFor.PolaroidStack:
/** Two or three prints; captions are hand-lettered. */
  photos: { src: string; alt: string; caption: string }[];
  /** The link text under the stack. */
  label: string;
  onOpen: () => void;

dtsPropsFor.ShopLink:
entry: {
    id: "leftover-crack" | "reagan-youth" | "gash";
    band: string;
    role: string;
    years: string;
    blurb: string;
    highlights: { label: string; detail: string }[];
    photos: { src: string; alt: string; width: number; height: number }[];
  };
  onOpen: (band: "leftover-crack" | "reagan-youth" | "gash") => void;
